<?php declare(strict_types=1);namespace App\Services;use App\Core\Config;use App\Core\Crypto;use App\Models\AuditLog;use App\Models\Release;final class UpdateService{public static function releasesDir():string{$X=(string)Config::get('updates.releases_dir',TP_ROOT.'/storage/releases');if(!is_dir($X)){@mkdir($X,0775,true);}return rtrim($X,'/');}public static function signSha256(string $j):string{return base64_encode(Crypto::sign(strtolower($j)));}public static function verifySignature(string $D,string $f,?string $A=null):bool{$O=base64_decode($f,true);return $O!==false&&Crypto::verify(strtolower($D),$O,$A);}public static function publishFromFile(string $c,array $b,?string $f=null):array{$g=self::validVersion($b['version']??'');$E=($b['channel']??'stable')==='beta'?'beta':'stable';$Z=self::releasesDir().'/'.$g;if(!is_dir($Z)){mkdir($Z,0775,true);}$d='toutpvr-'.$g.'.tar.gz';$P=$Z.'/'.$d;if(!@rename($c,$P)&&!copy($c,$P)){throw new \RuntimeException('Impossible de déplacer le paquet');}$S=hash_file('sha256',$P);$b['sha256']=$S;$b['size']=filesize($P);$b['signature']=self::signSha256($S);$b['file_path']='storage/releases/'.$g.'/'.$d;$b['channel']=$E;$b['download_url']=$b['download_url']??rtrim((string)Config::get('app.url'),'/').'/download/'.$g.'/'.$d;return self::_k4d1g($b);}public static function publishManifest(array $C,bool $E=false):array{$w=self::validVersion($C['version']??'');if(empty($C['sha256'])||!preg_match('/^[a-f0-9]{64}$/i',(string)$C['sha256'])){throw new \InvalidArgumentException('sha256 invalide');}if(empty($C['download_url'])){throw new \InvalidArgumentException('download_url requis');}$C['version']=$w;$C['channel']=($C['channel']??'stable')==='beta'?'beta':'stable';if(!empty($C['signature'])){if(!self::verifySignature((string)$C['sha256'],(string)$C['signature'])){throw new \InvalidArgumentException('signature invalide pour la clé publique du portail');}}elseif($E){throw new \InvalidArgumentException('signature requise');}else{$C['signature']=self::signSha256((string)$C['sha256']);}if($E){$c=$C['changelog']??[];if(!is_array($c)||trim((string)($c['fr']??''))===''||trim((string)($c['en']??''))===''){throw new \InvalidArgumentException('changelog fr et en requis');}if(Release::query()->where('version',$w)->where('channel',$C['channel'])->where('is_active',1)->count()>0){throw new ConflictException('version déjà publiée sur ce canal');}$m=self::releasesDir().'/'.$w.'/toutpvr-'.$w.'.tar.gz';if(is_file($m)){if(!hash_equals(hash_file('sha256',$m),strtolower((string)$C['sha256']))){throw new \InvalidArgumentException('sha256 différent du fichier déposé (checksum_mismatch)');}if(isset($C['size'])&&(int)$C['size']!==filesize($m)){throw new \InvalidArgumentException('taille différente du fichier déposé');}$C['file_path']='storage/releases/'.$w.'/toutpvr-'.$w.'.tar.gz';$C['download_url']=rtrim((string)Config::get('app.url'),'/').'/download/'.$w.'/toutpvr-'.$w.'.tar.gz';}}return self::_k4d1g($C);}private static function _k4d1g(array $m):array{$K=$m['changelog']??[];if(is_string($K)){$K=['fr'=>$K];}$i=Release::query()->where('version',$m['version'])->where('channel',$m['channel'])->first();$b=['version'=>$m['version'],'channel'=>$m['channel'],'published_at'=>isset($m['published_at'])?gmdate('Y-m-d H:i:s',strtotime((string)$m['published_at'])?:time()):now(),'notes_url'=>$m['notes_url']??null,'download_url'=>$m['download_url']??null,'file_path'=>$m['file_path']??$i['file_path']??null,'sha256'=>strtolower((string)$m['sha256']),'signature'=>(string)$m['signature'],'size'=>(int)($m['size']??0),'min_version'=>self::validVersion($m['min_version']??'1.0.0'),'changelog'=>$K,'is_active'=>1];if($i){Release::update((int)$i['id'],$b);$u=(int)$i['id'];}else{$b['created_at']=now();$u=Release::create($b);}AuditLog::log('release.publish',$m['version'],['channel'=>$m['channel'],'sha256'=>$b['sha256']]);return Release::find($u);}public static function validVersion(string $a):string{$a=trim($a);if(!preg_match('/^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/',$a)){throw new \InvalidArgumentException('Version semver invalide : '.$a);}return $a;}public static function latest(string $g,?string $c):?array{$i=Release::latest($g);if(!$i){return null;}return $i;}}